33440.a:
```hcl
resource "aws_instance" "api" {
  ami           = data.aws_ami.app.id
  instance_type = var.type

  lifecycle {
    precondition {
      condition     = data.aws_ami.app.architecture == "arm64"
      error_message = "Graviton uchun arm64 AMI kerak"
    }
    postcondition {
      condition     = self.private_ip != ""
      error_message = "Private IP berilmadi"
    }
  }
}

check "health" {
  data "http" "api" { url = "https://api.example.com/health" }
  assert {
    condition     = data.http.api.status_code == 200
    error_message = "API health 200 emas"
  }
}
```
Foyda: xato plan bosqichida, tushunarli xabar bilan — modulni noto'g'ri ishlatish erta ushlanadi.

33441.a:
```yaml
- block:
    - name: Yangi versiyani o'rnatish
      unarchive: { src: "app-{{ ver }}.tgz", dest: /opt/app, remote_src: true }
    - name: Restart
      systemd: { name: app, state: restarted }
    - uri: { url: http://localhost:8080/health }
      retries: 5
      delay: 3
      register: h
      until: h.status == 200
  rescue:
    - name: Oldingi versiyaga qaytish
      file: { src: /opt/app/releases/prev, dest: /opt/app/current, state: link }
    - systemd: { name: app, state: restarted }
    - fail: { msg: "Deploy fail, rollback qilindi" }
  always:
    - file: { path: /tmp/app.tgz, state: absent }
```
`rescue` ichida `fail` — aks holda play "muvaffaqiyatli" ko'rinadi.

